import"./chunk-7CGTOI24.js";var e={slug:"zelda-ocarina-of-time-remake-switch-2",title:"Ocarina of Time renasce no Switch 2: o cl\xE1ssico de 1998 est\xE1 de volta",dek:"O remake de The Legend of Zelda: Ocarina of Time saiu em 5 de novembro, s\xF3 no Switch 2. Veja o que se sabe e por que ele importa tanto.",section:"games",kind:"noticia",tags:["Nintendo","Zelda","Switch 2","Remake"],date:"2026-11-05",hero:{ref:"game:405460",pick:0,alt:"Arte do remake de The Legend of Zelda: Ocarina of Time para Nintendo Switch 2"},body:[{p:"Est\xE1 nas lojas desde esta quinta-feira (5) o remake de *The Legend of Zelda: Ocarina of Time*, exclusivo do **Nintendo Switch 2**. \xC9 a primeira vez que a Nintendo refaz do zero a aventura que, em 1998, levou a s\xE9rie para o 3D no Nintendo 64."},{h2:"Do an\xFAncio ao lan\xE7amento"},{p:"O projeto foi revelado em um Nintendo Direct em junho de 2026, com um teaser curto e poucas informa\xE7\xF5es. A data de 5 de novembro veio depois, e a Nintendo descreve o jogo como constru\xEDdo desde o in\xEDcio para o Switch 2. N\xE3o se trata, portanto, de um port com resolu\xE7\xE3o maior: \xE9 um remake completo, assinado pelo Nintendo EPD Production Group No. 3, o mesmo grupo respons\xE1vel por *Breath of the Wild* e *Tears of the Kingdom*."},{ficha:"game:405460"},{h2:"A hist\xF3ria que todo mundo conhece"},{p:"A premissa segue intacta: Ganondorf quer roubar a Triforce do Reino Sagrado para dominar o mundo, e Link precisa se tornar o Her\xF3i do Tempo para impedir. O jogo alterna entre a inf\xE2ncia e a vida adulta do her\xF3i, uma estrutura que ainda hoje parece ousada."},{img:"game:405460",pick:3,caption:"O remake redesenha Hyrule para o hardware do Switch 2. Imagem de divulga\xE7\xE3o."},{h2:"Por que Ocarina importa"},{p:"Muita coisa que hoje parece \xF3bvia em aventuras de a\xE7\xE3o em 3D se popularizou aqui, como a mira travada em inimigos durante o combate. Para quem cresceu com o cartucho, \xE9 um reencontro. Para quem nunca jogou, \xE9 a chance de conhecer o cl\xE1ssico sem a barreira t\xE9cnica de um jogo de quase tr\xEAs d\xE9cadas."},{p:"O original tamb\xE9m tem um cap\xEDtulo brasileiro: segundo o IGDB, a distribui\xE7\xE3o por aqui passou pela Gradiente, parceira da Nintendo no pa\xEDs naquela \xE9poca."},{ficha:"game:1029"},{h2:"Vale a pena para quem j\xE1 jogou?"},{p:"A reda\xE7\xE3o ainda est\xE1 jogando e a review completa sai nas pr\xF3ximas semanas. Por enquanto, a pergunta que fazemos \xE9 simples: um remake s\xF3 justifica o pre\xE7o se tiver identidade pr\xF3pria. A d\xFAvida \xE9 se a Nintendo vai al\xE9m da reforma visual, e o veredito fica para quando os cr\xE9ditos subirem."},{box:"Se voc\xEA quer saber em que ordem jogar a s\xE9rie, preparamos um [guia de por onde come\xE7ar em Zelda](/artigo/guia-por-onde-comecar-em-zelda), com caminhos para iniciantes e veteranos.",title:"Novo na s\xE9rie?"}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{1029:{id:1029,name:"The Legend of Zelda: Ocarina of Time",type:"Jogo principal",cover:"co3nnx",shots:[],arts:["ar3p2t"],genres:["Quebra-cabe\xE7a","Aventura","A\xE7\xE3o","Fantasia"],modes:["Single player"],devs:["Nintendo Entertainment Analysis & Development"],pubs:["Nintendo","Gradiente"],released:"1998",releases:{"Nintendo 64":"1998",Wii:"2007-02-23"},classInd:"AD"},405460:{id:405460,name:"The Legend of Zelda: Ocarina of Time",type:"Remake",cover:"cocv5r",shots:["sc153eu","sc13qrq","sc153ew","sc153ev","sc153ex","sc153et"],arts:["ar6knj","ar6zby","ar6zbx","ar6bmb"],genres:["Quebra-cabe\xE7a","Aventura","A\xE7\xE3o","Fantasia"],modes:["Single player"],devs:["Nintendo EPD Production Group No. 3"],pubs:["Nintendo"],released:"2026-11-05",releases:{"Switch 2":"2026-11-05"},classInd:"10"}},movies:{},tv:{}};export{o as media,e as post};
